window.anime = window.anime || function (options) {
    const targets = typeof options.targets === 'string'
        ? Array.from(document.querySelectorAll(options.targets))
        : Array.isArray(options.targets)
            ? options.targets
            : [options.targets].filter(Boolean);

    const duration = Number(options.duration || 450);
    const delayOption = options.delay || 0;
    const easing = options.easing || 'easeOutCubic';
    const start = performance.now();
    const initial = new Map();

    const ease = (t) => {
        if (easing.includes('Back')) {
            const c1 = 1.70158;
            const c3 = c1 + 1;
            return 1 + c3 * Math.pow(t - 1, 3) + c1 * Math.pow(t - 1, 2);
        }
        return 1 - Math.pow(1 - t, 3);
    };

    const toValue = (value, index) => {
        if (typeof value === 'function') {
            return value(targets[index], index, targets.length);
        }
        return value;
    };

    const numericProps = ['opacity', 'translateY', 'translateX', 'scale'];
    targets.forEach((target, index) => {
        const computed = getComputedStyle(target);
        initial.set(target, {
            opacity: Number(computed.opacity || 1),
            translateX: 0,
            translateY: 0,
            scale: 1,
            delay: Number(toValue(delayOption, index) || 0),
        });
    });

    const tick = (now) => {
        let done = true;

        targets.forEach((target, index) => {
            const base = initial.get(target);
            const elapsed = Math.max(0, now - start - base.delay);
            const progress = Math.min(1, elapsed / duration);
            const eased = ease(progress);

            if (progress < 1) {
                done = false;
            }

            const current = {};
            numericProps.forEach((prop) => {
                if (options[prop] === undefined) {
                    current[prop] = base[prop];
                    return;
                }

                const raw = toValue(options[prop], index);
                const values = Array.isArray(raw) ? raw : [base[prop], raw];
                const from = Number(values[0]);
                const to = Number(values[1]);
                current[prop] = from + (to - from) * eased;
            });

            target.style.opacity = String(current.opacity);
            target.style.transform = `translate(${current.translateX}px, ${current.translateY}px) scale(${current.scale})`;
        });

        if (!done) {
            requestAnimationFrame(tick);
        } else if (typeof options.complete === 'function') {
            options.complete();
        }
    };

    requestAnimationFrame(tick);
};
